import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner = address(0xABCD);

    function setUp() public { c = new C(); }

    // fuzz a deposit amount; for the property we require that for any nonzero balance,
    // withdrawAll empties the contract in the correct implementation. The mutant leaves 1 wei.
    function testFuzz_property(uint256 depositAmount) public {
        // keep domain wide but exclude the trivial zero case where both behave the same
        vm.assume(depositAmount > 0);
        // fund the owner EOA so it can send value
        vm.deal(owner, depositAmount);
        // perform the deposit via fallback by sending Ether to the contract from owner
        vm.prank(owner);
        (bool sent,) = address(c).call{value: depositAmount}("");
        require(sent);

        // now call withdrawAll as the owner
        vm.prank(owner);
        c.withdrawAll();

        // General fact: after withdrawAll by the owner, the contract balance must be zero.
        // The reference satisfies this for every nonzero depositAmount, the mutant that
        // subtracts 1 wei will leave 1 wei for some depositAmount values and thus fail.
        assertTrue(address(c).balance == 0);
    }
}

