contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameter: an arbitrary nonnegative amount to fund the contract
    function testFuzz_property(uint256 fundAmount) public {
        // keep domain wide but avoid overflow/no-op: require fundAmount fits in balance operations
        // also require fundAmount <= type(uint128).max to keep VM deals reasonable
        vm.assume(fundAmount <= address(this).balance + 1e30);

        // make the test caller the owner (deployer created c in setUp)
        address owner = address(this);

        // fund owner so they can send fundAmount to c
        vm.deal(owner, fundAmount);

        // If fundAmount is zero, withdrawAll trivially leaves balance 0 for both reference and mutant.
        // We keep fundAmount unconstrained so fuzzer can find >=1 to distinguish mutant.

        // send fundAmount wei to c as owner
        // no prank needed because this contract is the deployer/owner
        (bool sent, ) = address(c).call{value: fundAmount}("");
        require(sent);

        // Call withdrawAll as owner (this contract)
        // capture whether the call succeeds to observe behavior; reference should succeed
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // After a successful withdrawAll on the reference, the contract balance must be 0 for EVERY admissible input.
        // We assert that if the call succeeded, address(c).balance == 0. (Single universal assertion reading c.)
        // This is true for the correct contract; the mutant that withdraws balance-1 will leave 1 wei when fundAmount>=1
        if (ok) {
            assertTrue(address(c).balance == 0);
        } else {
            // If the call reverted, the reference would also revert; to keep the property universal we assert false only when ok==false is impossible for reference.
            // But withdrawAll on reference should not revert, so reaching here indicates failure; keep assertion to reflect observed behavior
            assertTrue(false);
        }
    }
}

