    C c;
    function setUp() public { c = new C(); }

    // fuzz parameter: amount the owner funds the contract with before calling withdrawAll
    function testFuzz_property(uint256 fundAmount) public {
        // Keep domain wide but restrict to realistic bounds so arithmetic in contract doesn't underflow
        // withdrawAll in mutant does `balance - 1`, so we must avoid underflow when balance == 0 for the reference run.
        // We allow both 0 and >=1; the property we assert will hold for all (see comment below).
        // Bound to a reasonably large value to avoid vm.deal overflow in some environments
        fundAmount = bound(fundAmount, 0, 1 ether);

        // The owner is the test contract by default (deployed C set owner=msg.sender in setUp), so fund from address(this)
        if (fundAmount > 0) {
            vm.deal(address(this), fundAmount);
            // send ETH into c so that address(c).balance == fundAmount
            (bool s, ) = address(c).call{value: fundAmount}("");
            require(s);
        }

        // Precondition: ensure owner is this test contract (true by C constructor)
        // Call withdrawAll as owner (this contract)
        // It should complete; wrap in try/catch to convert revert into a boolean if needed by mutant
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule to assert: for the correct contract, withdrawAll always succeeds (does not revert) when called by the owner.
        // The mutant may still succeed but for balances >=1 will leave 1 wei behind; however the safest universal property
        // that holds for all admissible inputs on reference C is that the call does not revert when invoked by owner.
        // Therefore we assert that withdrawAll did not revert.
        assertTrue(ok);
    }
}

