        // send the funds to the contract using low-level call so fallback() increments depositsCount
        (bool sent, ) = address(c).call{value: fundAmount}("");
        require(sent);

        // Ensure we only consider the interesting case where some value was sent
        vm.assume(address(c).balance == fundAmount);

        // Owner is the test contract deployer (msg.sender at construction). By default c.owner == address(this)
        // Call withdrawAll as owner
        // No prank necessary since setUp deployer is this test contract
        // Wrap call to observe success and then assert the universal property
        bool ok;
        try c.withdrawAll{ }() {
            ok = true;
