        require(ok);

        // Now attempt withdraw in two modes. If withdrawFromContract==false, have the owner call withdraw (should succeed in both ref and mutant).
        // If withdrawFromContract==true, have a helper contract call c.withdraw — the helper will attempt to call c.withdraw as msg.sender == address(helper).
        // The correct contract should NOT permit withdraw to succeed when msg.sender == address(helper) (unless helper somehow is owner, which it is not).

        // Deploy helper that will call c.withdraw
        CallerHelper helper = new CallerHelper();
